{
  "probability": 0.99,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "By February 2026, IOM data show 606 deaths/missing on the Mediterranean; this pace makes reaching 1,000 by end-April plausible if March–April remain elevated.",
    "Main drivers are weather-driven spikes, persistent high migrant flow, and variations in SAR capacity; better SAR or reporting could dampen the tally.",
    "Historical annual tolls (~2,100–2,400) provide a base-rate anchor, but near-term dynamics dominate the short window before May."
  ],
  "confidence": "high",
  "narrative": "Using the IOM Missing Migrants Project as the anchor, the observed pace through February 2026 implies a high likelihood of crossing 1,000 deaths before May if the March–April window remains deadly. Key drivers include weather-related fatalities, ongoing crossing attempts, and SAR capacity; reporting lag and policy shifts add uncertainty that keeps the outcome calibrated near the upper bound.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference-class anchor based on central Mediterranean death toll since 2014; prior consensus suggests 1,000+ fatalities before May is plausible given unusually high early-2026 death tolls (606 by February) and historical annual totals in the low- to mid-2,000s."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean deaths through February 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by February imply March–April could add hundreds; sustaining this pace is the primary driver toward 1,000+ by late April."
      },
      {
        "factor": "Weather events (Storm Harry)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather increases fatality risk on crossings, contributing to the upward trajectory."
      },
      {
        "factor": "Central Mediterranean migrant flow volume",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher inflows raise exposure and fatalities, raising the odds of crossing 1,000 by April."
      },
      {
        "factor": "Search-and-rescue capacity and policy responses",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR or safer paths reduce deaths, offsetting risk."
      },
      {
        "factor": "Data reporting completeness and lag",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Revisions or late reporting could shift counts; by end-April, data completeness will inform the tally."
      }
    ],
    "synthesis_rationale": "A Bayesian-style synthesis weights the strong February pace and weather/flow drivers toward a high probability of reaching 1,000, with down-weighting from SAR improvements and reporting lags; calibration acknowledges correlated factors and uncertainty, yielding a near-maximum posterior of 0.99 with a plausible 0.92–0.99 range."
  }
}

